page('videos.html', 'Science videos', 'Watch visual science explainers about IceCube, neutrinos, optogenetics and more.', videos)

schools = intro('FOR SCHOOLS / GRADES 8–12', 'A classroom full of questions.', 'Engaging talks and workshops designed to make students curious about evidence, ideas, and the people who investigate them.') + '''<section class="section wrap"><div class="section-heading">'''+eyebrow('WHAT WE CAN EXPLORE')+'''<h2>Start with a question.</h2></div><div class="three-grid">'''+card('SPACE', 'Our changing universe', 'The Big Bang, galaxies, black holes, dark matter, and how astronomers observe the distant universe.')+card('LIFE & MIND', 'The living world', 'Cells, the brain, and the methods scientists use to study biological systems.')+card('FUTURE TOOLS', 'AI and discovery', 'How scientists use data and models, with room to discuss uncertainty and responsible interpretation.')+'''</div></section>''' + section('FORMATS', 'Built for your students.', '<div class="detail-list"><div><strong>Interactive talk</strong><p>A visual, question-led session followed by open discussion.</p></div><div><strong>Workshop</strong><p>Small-group activities that turn a concept into an investigation.</p></div><div><strong>Series or science day</strong><p>Multiple sessions shaped around a theme, age group, or school goal.</p></div></div><p>Sessions can be adapted for grades 8–12. Duration, group size, and topic are agreed with each school.</p>') + '''<section class="photo-band wrap"><img src="assets/images/photos/bar-talk-audience.webp" alt="Audience engaged in a live science talk" loading="lazy"><div>'''+eyebrow('THE EXPERIENCE')+'''<h2>Participation over passive listening.</h2><p>Students are invited to make predictions, ask questions, and connect a scientific claim to the evidence behind it.</p></div></section>''' + section('BOOK A SESSION', 'Tell us about your school.', '<p>Share your city, student group, preferred date, and the questions your students are asking.</p>'+link('Enquire about a school programme', 'contact.html?interest=school', 'button'))
